"""Validate the Dart side-profile proposal and display matched collision views."""
import json
from pathlib import Path
from export import OUT,hub
r=json.loads((OUT/'verification.json').read_text());proof=json.loads((OUT/'geometry-verification.json').read_text());deck=json.loads((OUT/'deck-ray-checks.json').read_text());ccd=json.loads((OUT/'mesh-ccd-result.json').read_text());renders=json.loads((OUT/'renders.json').read_text());assert len(renders['views'])==24
for row in renders['views']:assert hub.scan.digest(Path(row['path']))==row['sha256']
for path,h in r['input_pins'].items():assert hub.scan.digest(Path(path))==h
assert hub.scan.digest(Path(r['candidate_collision']))==r['candidate_sha256']
assert ccd['exit_code']==0 and ccd['temporary_test_removed']and hub.scan.digest(OUT/'mesh-ccd-fixture.txt')==ccd['fixture_sha256']
assert '240 shots passed'in(OUT/'mesh-ccd.log').read_text()
placement=json.loads((OUT/'mesh-ccd-placement.json').read_text());assert hub.scan.digest(Path(placement['manifest']))==placement['manifest_sha256']
paths={str(node):{scope:{view:{stage:str(OUT/f'node{node}-{scope}-{view}-{stage}.webp')for stage in ['source','candidate']}for view in ['oblique','side','end']}for scope in ['frame','station']}for node in [354,587]}
html='''<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><style>
body{font-family:var(--font-sans);font-size:14px;line-height:1.5;color:var(--foreground)}p{margin:0 0 12px}.controls{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}select{font:inherit;color:inherit;background:var(--background);padding:7px;border:1px solid var(--border);border-radius:var(--radius);max-width:100%}.images{display:grid;grid-template-columns:1fr 1fr;gap:10px}figure{margin:0}figcaption{margin-bottom:6px}img{width:100%;display:block;border-radius:var(--radius)}.muted{color:var(--muted-foreground);font-size:13px}table{width:100%;border-collapse:collapse;margin:14px 0;font-size:13px}th,td{text-align:left;padding:8px 4px;border-bottom:1px solid var(--border)}.note{padding:16px;background:var(--card);border-radius:var(--radius);margin:14px 0}</style></head><body>
<p><strong>Next trial: simpler Dart side-frame profiles.</strong><br>Grooves and small fittings become closed profile solids. The large side openings remain, while the main deck, crossbars and door geometry stay exact. All visuals remain unchanged.</p>
<div class="controls"><select id="node" aria-label="Frame"><option value="354">Frame A</option><option value="587">Frame B</option></select><select id="scope" aria-label="Scope"><option value="frame">Frame only</option><option value="station">Station context</option></select><select id="camera" aria-label="Camera"><option value="oblique">Oblique</option><option value="side">Side</option><option value="end">End</option></select></div>
<div class="images"><figure><figcaption>Previous collision</figcaption><img id="before" alt="Detailed Dart frame collision"></figure><figure><figcaption>Side profiles</figcaption><img id="after" alt="Simplified Dart frame side profiles"></figure></div><p class="muted" style="margin-top:8px">Blue: selected side triangles before. Orange: replacement profiles. Grey: exact retained geometry. These colors show collision only.</p>
<table><tr><th>Both frames</th><th>Before</th><th>Proposal</th></tr><tr><td>Side triangles</td><td>18,358</td><td>3,872</td></tr><tr><td>Whole frame owners</td><td>34,870</td><td>20,384</td></tr><tr><td>New native primitives</td><td>—</td><td>0</td></tr></table>
<p><strong>14,486 triangles saved.</strong> The new outlines stay mesh-backed. A native convex decomposition would add many leaves, so that is not assumed to be the faster option.</p>
<div class="note"><strong>Coverage and projectile checks pass.</strong> All 18,358 replaced source triangles are enclosed by the new solids. All 240 projectile CCD shots pass against the actual profile triangle meshes. The large opening cores stay clear, and 1,554 deck rays retain exactly the same first-hit heights.</div>
<p>Small holes and channels close; some boundaries thicken slightly. The retained 16,512 frame triangles keep exact attributes and indices. All 616 other collision owners and every visual asset stay exact.</p>
<p class="muted">If adopted, whole-map remaining mesh becomes 372,036 triangles + the unchanged 80 cylinders, 8 boxes and 33 hulls. Runtime timing and full-field traversal/door integration remain untested. This new Dart trial is uncommitted and uninstalled; the accepted head/Rune checkpoint remains unchanged.</p>
<script>const paths=PATHS;function update(){const p=paths[node.value][scope.value][camera.value];before.src=p.source;after.src=p.candidate;}for(const id of ['node','scope','camera'])document.getElementById(id).addEventListener('change',update);update();console.log('Dart side profiles: 24 matched views, 240 CCD shots passed');</script></body></html>'''.replace('PATHS',json.dumps(paths))
(OUT/'gallery.html').write_text(html)
hashes={str(p.relative_to(OUT)):hub.scan.digest(p)for p in OUT.rglob('*')if p.is_file()and p.name not in ['gallery.html','final-verification.json']}
(OUT/'final-verification.json').write_text(json.dumps(dict(geometry=proof,deck_checks=deck,ccd=ccd,matched_images=24,artifact_sha256=hashes,installed=False),indent=2)+'\n');print('Verified coverage, deck rays, 240 CCD shots and 24 matched views.')
